{"command": "cd /workspace && python3 -c "
# Dump pattern 7 contents
import subprocess, json
calls = []
for row in range(64):
    for ch in range(8):
        r = subprocess.run(['ft2','call','pattern_get_cell',json.dumps({'pattern':7,'row':row,'channel':ch})],capture_output=True,text=True)
        d = json.loads(r.stdout)['content'][0]['text']
        d = json.loads(d)
        if d['note'] or d['instrument'] or d['effect'] or d['volume']:
            calls.append((row, ch, d))
# Print as grid
print(f'{'Row':>3} ' + '  '.join(f'Ch{c}      ' for c in range(8)))
cells = {}
for row, ch, d in calls:
    cells[(row,ch)] = d
for row in range(55, 64):
    line = f'{row:3d} '
    for ch in range(8):
        d = cells.get((row,ch))
        if d:
            note = d.get('note_name','') or ('===' if d['note']==97 else '---')
            inst = d.get('instrument',0)
            vol = d.get('volume',0)
            s = f'{note:3s}{inst:02d}{vol:02d}  '
        else:
            s = '---      '
        line += s
    print(line)
""}

